# -*- coding: utf-8 -*-
"""Localized dua titles and translations (en, ur, hi, bn, id)."""

LANGS = ("en", "ur", "hi", "bn", "id")


def _pack(parts, fallback):
    values = {
        "en": (parts[0] or fallback or "").strip() or fallback,
        "ur": (parts[1] or "").strip(),
        "hi": (parts[2] or "").strip(),
        "bn": (parts[3] or "").strip(),
        "id": (parts[4] or "").strip(),
    }
    english = values["en"]
    return {lang: (values[lang] or english) for lang in LANGS}


