# translation meaning: (en unused/override, ur, hi, bn, id) — en comes from seed unless set
TRANSLATIONS = {
    "eating-start": ("In the name of Allah.", "اللہ کے نام سے۔", "अल्लाह के नाम से।", "আল্লাহর নামে।", "Dengan nama Allah."),
    "eating-forget": ("In the name of Allah at its beginning and at its end.", "اللہ کے نام سے اس کی ابتدا اور انتہا میں۔", "अल्लाह के नाम से इसकी शुरुआत और अंत में।", "আল্লাহর নামে এর শুরুতে ও শেষে।", "Dengan nama Allah pada awal dan akhirnya."),
    "eating-end": ("Praise be to Allah Who fed me this and provided it for me, with no power or might from myself.", "تمام تعریفیں اس اللہ کے لیے جس نے مجھے یہ کھلایا اور بغیر میری طاقت کے عطا فرمایا۔", "सारी प्रशंसा अल्लाह के लिए जिसने मुझे यह खिलाया और मेरी शक्ति के बिना दिया।", "সমস্ত প্রশংসা আল্লাহর, যিনি আমাকে এটি খাওয়ালেন এবং আমার শক্তি ছাড়াই দিলেন।", "Segala puji bagi Allah yang memberiku makan ini tanpa daya dan kekuatan dariku."),
    "drinking": ("In the name of Allah.", "اللہ کے نام سے۔", "अल्लाह के नाम से।", "আল্লাহর নামে।", "Dengan nama Allah."),
    "milk": ("O Allah, bless it for us and give us more of it.", "اے اللہ! اس میں ہمارے لیے برکت دے اور اس سے ہمیں مزید عطا فرما۔", "ऐ अल्लाह! इसमें हमारे लिए बरकत दे और हमें इससे और दे।", "হে আল্লাহ, এতে আমাদের জন্য বরকত দাও এবং আরও দাও।", "Ya Allah, berkahilah kami padanya dan tambahkan kepada kami darinya."),
    "waking": ("Praise be to Allah Who gave us life after He caused us to die, and to Him is the resurrection.", "تمام تعریفیں اس اللہ کے لیے جس نے ہمیں موت کے بعد زندگی دی، اور اسی کی طرف اٹھنا ہے۔", "सारी प्रशंसा अल्लाह के लिए जिसने हमें मृत्यु के बाद जीवन दिया, और उसी की ओर उठना है।", "সমস্ত প্রশংসা আল্লাহর, যিনি মৃত্যুর পর আমাদের জীবন দিলেন, আর তাঁর দিকেই পুনরুত্থান।", "Segala puji bagi Allah yang menghidupkan kami setelah mematikan kami, dan kepada-Nya kebangkitan."),
    "sleeping": ("In Your name, O Allah, I die and I live.", "اے اللہ! تیرے نام کے ساتھ میں مرتا ہوں اور جیتا ہوں۔", "ऐ अल्लाह! तेरे नाम से मैं मरता हूँ और जीता हूँ।", "হে আল্লাহ, তোমার নামে আমি মরি ও বাঁচি।", "Dengan nama-Mu, ya Allah, aku mati dan aku hidup."),
    "sleeping-long": ("O Allah, in Your name I die and I live.", "اے اللہ! میں تیرے نام سے مرتا ہوں اور جیتا ہوں۔", "ऐ अल्लाह! मैं तेरे नाम से मरता हूँ और जीता हूँ।", "হে আল্লাহ, আমি তোমার নামে মরি ও বাঁচি।", "Ya Allah, dengan nama-Mu aku mati dan aku hidup."),
    "toilet-enter": ("O Allah, I seek refuge in You from the male and female unclean spirits.", "اے اللہ! میں ناپاک نر اور مادہ جنّات سے تیری پناہ مانگتا ہوں۔", "ऐ अल्लाह! मैं नर और मादा नापाक जिन्नों से तेरी पनाह माँगता हूँ।", "হে আল্লাহ, আমি নর-নারী অপবিত্র জিন থেকে তোমার আশ্রয় চাই।", "Ya Allah, aku berlindung kepada-Mu dari setan laki-laki dan perempuan."),
    "toilet-exit": ("I seek Your forgiveness.", "میں تیری مغفرت چاہتا ہوں۔", "मैं तेरी मग़फ़िरत चाहता हूँ।", "আমি তোমার ক্ষমা চাই।", "Aku memohon ampunan-Mu."),
    "wudu-start": ("In the name of Allah.", "اللہ کے نام سے۔", "अल्लाह के नाम से।", "আল্লাহর নামে।", "Dengan nama Allah."),
    "wudu-end": ("I bear witness that there is no god but Allah, alone without partner, and that Muhammad is His servant and Messenger.", "میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اور محمد اس کے بندے اور رسول ہیں۔", "मैं गवाही देता हूँ कि अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है बिना साझी के, और मुहम्मद उसके बंदे और रसूल हैं।", "আমি সাক্ষ্য দিই যে আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক অংশীদারহীন, আর মুহাম্মদ তাঁর বান্দা ও রাসূল।", "Aku bersaksi tiada tuhan selain Allah, Yang Esa tanpa sekutu, dan Muhammad adalah hamba dan Rasul-Nya."),
    "home-enter": ("In the name of Allah we enter, in the name of Allah we leave, and upon Allah our Lord we place our trust.", "ہم اللہ کے نام سے داخل ہوئے، اللہ کے نام سے نکلے، اور اپنے رب اللہ پر بھروسہ کیا۔", "हम अल्लाह के नाम से दाख़िल हुए, अल्लाह के नाम से निकले, और अपने रब अल्लाह पर भरोसा किया।", "আমরা আল্লাহর নামে প্রবেশ করি, আল্লাহর নামে বের হই, আর আমাদের রব আল্লাহর উপর ভরসা করি।", "Dengan nama Allah kami masuk, dengan nama Allah kami keluar, dan kepada Allah Tuhan kami kami bertawakal."),
    "home-exit": ("In the name of Allah, I place my trust in Allah, and there is no power and no strength except with Allah.", "اللہ کے نام سے، میں نے اللہ پر بھروسہ کیا، اور اللہ کے سوا کوئی طاقت و قوت نہیں۔", "अल्लाह के नाम से, मैंने अल्लाह पर भरोसा किया, और अल्लाह के सिवा कोई शक्ति नहीं।", "আল্লাহর নামে, আমি আল্লাহর উপর ভরসা করি, আর আল্লাহ ছাড়া কোনো শক্তি নেই।", "Dengan nama Allah, aku bertawakal kepada Allah, dan tiada daya serta kekuatan kecuali dengan Allah."),
    "masjid-enter": ("O Allah, open for me the gates of Your mercy.", "اے اللہ! میرے لیے اپنی رحمت کے دروازے کھول دے۔", "ऐ अल्लाह! मेरे लिए अपनी रहमत के दरवाज़े खोल दे।", "হে আল্লাহ, আমার জন্য তোমার রহমতের দরজা খুলে দাও।", "Ya Allah, bukakan untukku pintu-pintu rahmat-Mu."),
    "masjid-exit": ("O Allah, I ask You from Your bounty.", "اے اللہ! میں تجھ سے تیرا فضل مانگتا ہوں۔", "ऐ अल्लाह! मैं तुझसे तेरा फ़ज़्ल माँगता हूँ।", "হে আল্লাহ, আমি তোমার অনুগ্রহ চাই।", "Ya Allah, aku memohon kepada-Mu dari karunia-Mu."),
    "travel": ("Glory be to Him Who has subjected this to us, and we could not have it by our efforts. Indeed, to our Lord we will return.", "پاک ہے وہ ذات جس نے اسے ہمارے لیے مسخر کیا، حالانکہ ہم اس کے قابو میں نہ تھے، اور ہم اپنے رب کی طرف لوٹنے والے ہیں۔", "पाक है वह जिसने इसे हमारे वश में किया, जबकि हम इसे काबू न कर सकते थे, और हम अपने रब की ओर लौटने वाले हैं।", "পবিত্র তিনি যিনি এটিকে আমাদের অধীন করেছেন, আমরা তা পারতাম না, আর আমরা আমাদের রবের দিকেই ফিরব।", "Mahasuci Dia yang menundukkan ini bagi kami, padahal kami tidak mampu, dan sungguh kepada Tuhan kamilah kami kembali."),
    "travel-return": ("We return, repenting, worshipping, and praising our Lord.", "ہم لوٹنے والے، توبہ کرنے والے، عبادت کرنے والے اور اپنے رب کی حمد کرنے والے ہیں۔", "हम लौटने वाले, तौबा करने वाले, इबादत करने वाले और अपने रब की हम्द करने वाले हैं।", "আমরা ফিরছি, তওবা করছি, ইবাদত করছি এবং আমাদের রবের প্রশংসা করছি।", "Kami kembali, bertaubat, beribadah, dan memuji Tuhan kami."),
    "rain": ("O Allah, make it a beneficial downpour.", "اے اللہ! اسے فائدہ مند بارش بنا دے۔", "ऐ अल्लाह! इसे फ़ायदेमंद बारिश बना दे।", "হে আল্লাহ, এটিকে উপকারী বৃষ্টি বানাও।", "Ya Allah, jadikanlah hujan yang bermanfaat."),
    "thunder": ("Glory be to Him Whom thunder glorifies with His praise, and the angels from fear of Him.", "پاک ہے وہ جس کی حمد کے ساتھ بادل گرجتا ہے اور فرشتے اس کے خوف سے تسبیح کرتے ہیں۔", "पाक है वह जिसकी हम्द के साथ बादल गरजता है और फ़रिश्ते उसके ख़ौफ़ से तस्बीह करते हैं।", "পবিত্র তিনি যার প্রশংসায় বজ্র গর্জে ওঠে এবং ফেরেশতারা ভয়ে তাসবিহ করে।", "Mahasuci Dia yang guruh bertasbih dengan memuji-Nya, dan para malaikat karena takut kepada-Nya."),
    "wind": ("O Allah, I ask You for its good, the good within it, and the good it was sent with.", "اے اللہ! میں تجھ سے اس کی بھلائی، اس میں جو بھلائی ہے اور جس بھلائی کے ساتھ اسے بھیجا گیا مانگتا ہوں۔", "ऐ अल्लाह! मैं तुझसे इसकी भलाई, इसमें जो भलाई है और जिसके साथ इसे भेजा गया, माँगता हूँ।", "হে আল্লাহ, আমি এর কল্যাণ, এর ভিতরের কল্যাণ এবং যা নিয়ে পাঠানো হয়েছে তা চাই।", "Ya Allah, aku memohon kebaikannya, kebaikan yang ada padanya, dan kebaikan yang dengannya ia diutus."),
    "new-clothes": ("O Allah, praise is Yours; You have clothed me with it. I ask You for its good and the good for which it was made.", "اے اللہ! سب تعریف تیرے لیے ہے، تو نے مجھے یہ پہنایا۔ میں اس کی بھلائی اور اس مقصد کی بھلائی مانگتا ہوں جس کے لیے اسے بنایا گیا۔", "ऐ अल्लाह! सारी हम्द तेरी है, तूने मुझे यह पहनाया। मैं इसकी भलाई माँगता हूँ।", "হে আল্লাহ, প্রশংসা তোমার, তুমি আমাকে এটি পরিয়েছ। আমি এর কল্যাণ চাই।", "Ya Allah, segala puji bagi-Mu; Engkau memakaikannya padaku. Aku memohon kebaikannya."),
    "mirror": ("O Allah, as You have made my appearance beautiful, make my character beautiful.", "اے اللہ! جیسے تو نے میری صورت کو حسین بنایا، میرے اخلاق کو بھی حسین بنا دے۔", "ऐ अल्लाह! जैसे तूने मेरी सूरत हसीन बनाई, मेरे अख़लाक़ भी हसीन बना दे।", "হে আল্লাহ, যেমন তুমি আমার আকৃতি সুন্দর করেছ, আমার চরিত্রও সুন্দর করো।", "Ya Allah, sebagaimana Engkau indahkan penciptaanku, indahkan pula akhlakku."),
    "anger": ("I seek refuge in Allah from Satan, the accursed.", "میں اللہ کی پناہ مانگتا ہوں شیطان مردود سے۔", "मैं अल्लाह की पनाह माँगता हूँ शापित शैतान से।", "আমি অভিশপ্ত শয়তান থেকে আল্লাহর আশ্রয় চাই।", "Aku berlindung kepada Allah dari setan yang terkutuk."),
    "calamity": ("Indeed we belong to Allah and to Him we will return. O Allah, reward me in my calamity and replace it with something better.", "بے شک ہم اللہ کے ہیں اور اسی کی طرف لوٹیں گے۔ اے اللہ! مجھے میری مصیبت میں اجر دے اور اس سے بہتر بدل عطا فرما۔", "यक़ीनन हम अल्लाह के हैं और उसी की ओर लौटेंगे। ऐ अल्लाह! मुझे मेरी मुसीबत में अज्र दे और उससे बेहतर बदला दे।", "নিশ্চয় আমরা আল্লাহর এবং তাঁর দিকেই ফিরব। হে আল্লাহ, আমার বিপদে আমাকে প্রতিদান দাও এবং তার চেয়ে উত্তম দাও।", "Sungguh kita milik Allah dan kepada-Nya kita kembali. Ya Allah, berilah pahala dalam musibahku dan gantilah dengan yang lebih baik."),
    "anxiety": ("There is no god but You; glory be to You. Indeed I was among the wrongdoers.", "تیرے سوا کوئی معبود نہیں، تو پاک ہے، بے شک میں ظالموں میں سے تھا۔", "तेरे सिवा कोई माबूद नहीं, तू पाक है, यक़ीनन मैं ज़ालिमों में से था।", "তোমার ছাড়া কোনো ইলাহ নেই, তুমি পবিত্র, নিশ্চয় আমি জালিমদের অন্তর্ভুক্ত ছিলাম।", "Tiada tuhan selain Engkau, Mahasuci Engkau. Sungguh aku termasuk orang yang zalim."),
    "debt": ("O Allah, suffice me with what You have made lawful so that I have no need of what You have made unlawful, and make me independent of all others besides You.", "اے اللہ! اپنے حلال سے مجھے حرام سے بے نیاز کر دے، اور اپنے فضل سے مجھے تیرے سوا سب سے غنی کر دے۔", "ऐ अल्लाह! अपने हलाल से मुझे हराम से बेनियाज़ कर दे, और अपने फ़ज़्ल से मुझे तेरे सिवा सबसे ग़नी कर दे।", "হে আল্লাহ, তোমার হালাল দিয়ে হারাম থেকে আমাকে অমুখাপেক্ষী করো, আর তোমার অনুগ্রহে তুমি ছাড়া সবার থেকে অভাবমুক্ত করো।", "Ya Allah, cukupkan aku dengan yang halal sehingga aku tidak butuh yang haram, dan kayakan aku dengan karunia-Mu dari selain-Mu."),
    "rizq": ("O Allah, I ask You for lawful provision, beneficial knowledge, and accepted deeds.", "اے اللہ! میں تجھ سے پاکیزہ رزق، نفع بخش علم اور قبول عمل مانگتا ہوں۔", "ऐ अल्लाह! मैं तुझसे पाकीज़ा रिज़्क़, नफ़ेमंद इल्म और क़ुबूल अमल माँगता हूँ।", "হে আল্লাহ, আমি পবিত্র রিজিক, উপকারী ইলম ও কবুল আমল চাই।", "Ya Allah, aku memohon rezeki yang baik, ilmu yang bermanfaat, dan amal yang diterima."),
    "knowledge": ("My Lord, increase me in knowledge.", "اے میرے رب! میرے علم میں اضافہ فرما۔", "ऐ मेरे रब! मेरे इल्म में इज़ाफ़ा फ़रमा।", "হে আমার রব, আমার ইলম বাড়িয়ে দাও।", "Tuhanku, tambahkanlah ilmu kepadaku."),
    "parents": ("My Lord, have mercy on them as they raised me when I was small.", "اے میرے رب! ان پر رحم فرما جیسے انہوں نے بچپن میں میری پرورش کی۔", "ऐ मेरे रब! उन पर रहम फ़रमा जैसे उन्होंने बचपन में मेरी परवरिश की।", "হে আমার রব, তাদের প্রতি দয়া করো যেমন তারা ছোটবেলায় আমাকে লালন করেছে।", "Tuhanku, kasihilah keduanya sebagaimana mereka merawatku di waktu kecil."),
    "children": ("My Lord, grant me from Yourself good offspring. Indeed, You are the Hearer of supplication.", "اے میرے رب! مجھے اپنی طرف سے نیک اولاد عطا فرما، بے شک تو دعا سننے والا ہے۔", "ऐ मेरे रब! मुझे अपनी तरफ़ से नेक औलाद अता फ़रमा, यक़ीनन तू दुआ सुनने वाला है।", "হে আমার রব, তোমার কাছ থেকে আমাকে উত্তম সন্তান দাও, নিশ্চয় তুমি দোয়া শ্রবণকারী।", "Tuhanku, anugerahkan kepadaku keturunan yang baik dari sisi-Mu. Sungguh Engkau Maha Mendengar doa."),
    "spouse": ("Our Lord, grant us from our spouses and offspring comfort to our eyes.", "اے ہمارے رب! ہمیں ہماری بیویوں اور اولاد سے آنکھوں کی ٹھنڈک عطا فرما۔", "ऐ हमारे रब! हमें हमारी बीवियों और औलाद से आँखों की ठंडक अता फ़रमा।", "হে আমাদের রব, আমাদের স্ত্রী ও সন্তান থেকে চোখের শীতলতা দাও।", "Tuhan kami, anugerahkan kepada kami dari istri dan keturunan kami penyejuk mata."),
    "guest": ("O Allah, bless them in what You have provided them, forgive them, and have mercy on them.", "اے اللہ! جو تو نے انہیں دیا اس میں برکت دے، انہیں بخش دے اور ان پر رحم فرما۔", "ऐ अल्लाह! जो तूने उन्हें दिया उसमें बरकत दे, उन्हें बख़्श दे और उन पर रहम फ़रमा।", "হে আল্লাহ, তুমি যা দিয়েছ তাতে বরকত দাও, তাদের ক্ষমা করো ও দয়া করো।", "Ya Allah, berkahilah mereka pada apa yang Engkau berikan, ampunilah dan rahmatilah mereka."),
    "sneezing": ("Praise be to Allah.", "تمام تعریفیں اللہ کے لیے ہیں۔", "सारी प्रशंसा अल्लाह के लिए है।", "সমস্ত প্রশংসা আল্লাহর।", "Segala puji bagi Allah."),
    "sneezing-reply": ("May Allah have mercy on you.", "اللہ تجھ پر رحم کرے۔", "अल्लाह तुझ पर रहम करे।", "আল্লাহ তোমার প্রতি দয়া করুন।", "Semoga Allah merahmatimu."),
    "sneezing-reply2": ("May Allah guide you and set your affairs right.", "اللہ تمہیں ہدایت دے اور تمہارے حالات درست کرے۔", "अल्लाह तुम्हें हिदायत दे और तुम्हारे हाल दुरुस्त करे।", "আল্লাহ তোমাদের হিদায়াত দিন ও অবস্থা ভালো করুন।", "Semoga Allah memberimu petunjuk dan memperbaiki keadaanmu."),
    "visiting-sick": ("No harm, it is a purification, if Allah wills.", "کوئی حرج نہیں، ان شاء اللہ یہ پاکی ہے۔", "कोई हरज नहीं, इंशाअल्लाह यह पाकी है।", "কোনো ক্ষতি নেই, ইনশাআল্লাহ এটি পবিত্রতা।", "Tidak apa-apa, ini penyuci, insya Allah."),
    "for-sick": ("O Allah, Lord of mankind, remove the harm, heal him, for You are the Healer.", "اے اللہ! لوگوں کے رب، تکلیف دور فرما، اسے شفا دے، تو ہی شفا دینے والا ہے۔", "ऐ अल्लाह! लोगों के रब, तकलीफ़ दूर फ़रमा, उसे शिफ़ा दे, तू ही शिफ़ा देने वाला है।", "হে আল্লাহ, মানুষের রব, কষ্ট দূর করো, তাকে সুস্থ করো, তুমিই সুস্থদাতা।", "Ya Allah, Tuhan manusia, hilangkanlah penyakit, sembuhkanlah dia, Engkaulah Maha Penyembuh."),
    "after-adhan": ("O Allah, Lord of this perfect call and the prayer about to be performed, grant Muhammad the Wasila and virtue.", "اے اللہ! اس کامل دعوت اور قائم ہونے والی نماز کے رب، محمد کو وسیلہ اور فضیلت عطا فرما۔", "ऐ अल्लाह! इस कामिल दावत और क़ायम नमाज़ के रब, मुहम्मद को वसीला और फ़ज़ीलत अता फ़रमा।", "হে আল্লাহ, এই পরিপূর্ণ আহ্বান ও প্রতিষ্ঠিত সালাতের রব, মুহাম্মদকে ওসিলা ও মর্যাদা দাও।", "Ya Allah, Tuhan panggilan yang sempurna ini dan shalat yang akan didirikan, berilah Muhammad wasilah dan keutamaan."),
    "iqamah": ("May Allah establish it and make it perpetual.", "اللہ اسے قائم رکھے اور اسے دائم رکھے۔", "अल्लाह इसे क़ायम रखे और इसे दाइम रखे।", "আল্লাহ এটিকে প্রতিষ্ঠিত ও স্থায়ী রাখুন।", "Semoga Allah menegakkannya dan menjadikannya kekal."),
    "iftitah": ("Glory and praise be to You, O Allah. Blessed is Your name, exalted is Your majesty, and there is no god besides You.", "اے اللہ! تو پاک ہے اور تیری حمد ہے، تیرا نام بابرکت ہے، تیری شان بلند ہے، تیرے سوا کوئی معبود نہیں۔", "ऐ अल्लाह! तू पाक है और तेरी हम्द है, तेरा नाम बाबरकत है, तेरी शान बुलंद है, तेरे सिवा कोई माबूद नहीं।", "হে আল্লাহ, তুমি পবিত্র ও প্রশংসিত, তোমার নাম বরকতময়, তোমার মহিমা উচ্চ, তুমি ছাড়া কোনো ইলাহ নেই।", "Mahasuci Engkau, ya Allah, dan dengan memuji-Mu. Berkah nama-Mu, tinggi keagungan-Mu, dan tiada tuhan selain Engkau."),
    "ruku": ("Glory be to my Lord, the Magnificent.", "میرا رب عظیم پاک ہے۔", "मेरा रब अज़ीम पाक है।", "আমার মহান রব পবিত্র।", "Mahasuci Tuhanku Yang Mahaagung."),
    "sujud": ("Glory be to my Lord, the Most High.", "میرا رب اعلیٰ پاک ہے۔", "मेरा रब आला पाक है।", "আমার সর্বোচ্চ রব পবিত্র।", "Mahasuci Tuhanku Yang Mahatinggi."),
    "tashahhud": ("All compliments, prayers, and pure words are for Allah.", "تمام سلامیاں، نمازیں اور پاکیزہ باتیں اللہ کے لیے ہیں۔", "सारी तहिय्यात, नमाज़ें और पाकीज़ा बातें अल्लाह के लिए हैं।", "সমস্ত সম্ভাষণ, সালাত ও পবিত্র বাক্য আল্লাহর জন্য।", "Segala penghormatan, shalat, dan kebaikan milik Allah."),
    "salawat": ("O Allah, send blessings upon Muhammad and the family of Muhammad, as You sent blessings upon Ibrahim and the family of Ibrahim.", "اے اللہ! محمد اور آل محمد پر رحمت بھیج جیسے تو نے ابراہیم اور آل ابراہیم پر رحمت بھیجی۔", "ऐ अल्लाह! मुहम्मद और आले मुहम्मद पर रहमत भेज जैसे तूने इबराहीम और आले इबराहीम पर भेजी।", "হে আল্লাহ, মুহাম্মদ ও তাঁর পরিবারের প্রতি রহমত পাঠাও যেমন ইবরাহিম ও তাঁর পরিবারের প্রতি পাঠিয়েছিলে।", "Ya Allah, limpahkan shalawat kepada Muhammad dan keluarga Muhammad sebagaimana Engkau bershalawat kepada Ibrahim dan keluarga Ibrahim."),
    "qunoot": ("O Allah, guide me among those You have guided, and grant me well-being among those You have granted well-being.", "اے اللہ! مجھے ہدایت دے ان میں جنہیں تو نے ہدایت دی، اور عافیت دے ان میں جنہیں تو نے عافیت دی۔", "ऐ अल्लाह! मुझे हिदायत दे उनमें जिन्हें तूने हिदायत दी, और आफ़ियत दे उनमें जिन्हें तूने आफ़ियत दी।", "হে আল্লাহ, যাদের হিদায়াত দিয়েছ তাদের মধ্যে আমাকে হিদায়াত দাও, আর যাদের সুস্থতা দিয়েছ তাদের মধ্যে আমাকে সুস্থতা দাও।", "Ya Allah, tunjukilah aku bersama orang yang Engkau beri petunjuk, dan sejahterakan aku bersama orang yang Engkau sejahterakan."),
    "after-salam": ("I seek forgiveness from Allah (three times).", "میں اللہ سے بخشش مانگتا ہوں (تین بار)۔", "मैं अल्लाह से बख़्शिश माँगता हूँ (तीन बार)।", "আমি আল্লাহর কাছে ক্ষমা চাই (তিনবার)।", "Aku memohon ampun kepada Allah (tiga kali)."),
    "salam-after": ("O Allah, You are Peace and from You is peace. Blessed are You, O Owner of majesty and honor.", "اے اللہ! تو سلام ہے اور تجھ سے سلامتی ہے، تو بابرکت ہے اے عظمت و اکرام والے!", "ऐ अल्लाह! तू सलाम है और तुझसे सलामती है, तू बाबरकत है ऐ अज़मत व इकराम वाले!", "হে আল্লাহ, তুমি সালাম এবং তোমার থেকেই শান্তি, তুমি বরকতময় হে মহিমা ও সম্মানের অধিকারী।", "Ya Allah, Engkaulah Salam dan dari-Mu keselamatan. Maha berkah Engkau, wahai Pemilik keagungan dan kemuliaan."),
    "laylatul-qadr": ("O Allah, You are Pardoning and love to pardon, so pardon me.", "اے اللہ! تو معاف کرنے والا ہے، معافی کو پسند کرتا ہے، پس مجھے معاف فرما دے۔", "ऐ अल्लाह! तू माफ़ करने वाला है, माफ़ी को पसंद करता है, तो मुझे माफ़ फ़रमा दे।", "হে আল্লাহ, তুমি ক্ষমাশীল ও ক্ষমা ভালোবাসো, তাই আমাকে ক্ষমা করো।", "Ya Allah, Engkau Maha Pemaaf dan menyukai maaf, maka maafkanlah aku."),
    "ramadan-iftar": ("The thirst is gone, the veins are moistened, and the reward is confirmed, if Allah wills.", "پیاس جاتی رہی، رگیں تر ہو گئیں، اور اجر ثابت ہو گیا ان شاء اللہ۔", "प्यास चली गई, रगें तर हो गईं, और अज्र साबित हो गया इंशाअल्लाह।", "তৃষ্ণা চলে গেছে, শিরা সিক্ত হয়েছে, আর প্রতিদান নিশ্চিত হয়েছে ইনশাআল্লাহ।", "Dahaga telah hilang, urat telah basah, dan pahala telah tetap, insya Allah."),
    "suhoor": ("I intend to fast tomorrow in the month of Ramadan.", "میں نے رمضان کے مہینے کے کل کے روزے کی نیت کی۔", "मैंने रमज़ान के महीने के कल के रोज़े की नीयत की।", "আমি রমজান মাসের আগামীকালের রোজার নিয়ত করলাম।", "Aku berniat puasa esok hari di bulan Ramadan."),
    "breaking-fast-guest": ("May the fasting people break their fast with you, may the righteous eat your food, and may the angels send blessings upon you.", "روزہ دار تمہارے یہاں افطار کریں، نیک لوگ تمہارا کھانا کھائیں، اور فرشتے تم پر درود بھیجیں۔", "रोज़ादार तुम्हारे यहाँ इफ़्तार करें, नेक लोग तुम्हारा खाना खाएँ, और फ़रिश्ते तुम पर दुरूद भेजें।", "রোজাদার তোমাদের কাছে ইফতার করুক, সৎরা তোমাদের খাবার খাক, আর ফেরেশতারা তোমাদের প্রতি দরুদ পাঠাক।", "Semoga orang yang berpuasa berbuka di sisimu, orang saleh memakan makananmu, dan para malaikat bershalawat atasmu."),
    "istikhara": ("O Allah, I seek the good from You by Your knowledge, I seek ability from You by Your power, and I ask You from Your immense bounty.", "اے اللہ! میں تیرے علم سے خیر مانگتا ہوں، تیری قدرت سے طاقت چاہتا ہوں، اور تیرے عظیم فضل سے سوال کرتا ہوں۔", "ऐ अल्लाह! मैं तेरे इल्म से ख़ैर माँगता हूँ, तेरी क़ुदरत से ताक़त चाहता हूँ, और तेरे अज़ीम फ़ज़्ल से सवाल करता हूँ।", "হে আল্লাহ, তোমার ইলম দিয়ে কল্যাণ চাই, তোমার কুদরত দিয়ে সামর্থ্য চাই, আর তোমার বিপুল অনুগ্রহ চাই।", "Ya Allah, aku memohon kebaikan dengan ilmu-Mu, memohon kemampuan dengan kuasa-Mu, dan memohon karunia-Mu yang agung."),
    "protection": ("In the name of Allah, with Whose name nothing on earth or in heaven can cause harm, and He is the All-Hearing, All-Knowing.", "اللہ کے نام سے جس کے نام کے ساتھ زمین و آسمان کی کوئی چیز نقصان نہیں دے سکتی، اور وہ سننے والا جاننے والا ہے۔", "अल्लाह के नाम से जिसके नाम के साथ ज़मीन व आसमान की कोई चीज़ नुक़सान नहीं दे सकती, और वह सुनने वाला जानने वाला है।", "আল্লাহর নামে যাঁর নামে যমীন ও আসমানের কিছুই ক্ষতি করতে পারে না, তিনি সর্বশ্রোতা সর্বজ্ঞ।", "Dengan nama Allah yang dengan nama-Nya tidak ada sesuatu di bumi dan langit yang membahayakan, dan Dia Maha Mendengar Maha Mengetahui."),
    "evil-eye": ("I seek refuge in the perfect words of Allah from every devil and poisonous creature, and from every evil eye.", "میں اللہ کے کامل کلمات کی پناہ مانگتا ہوں ہر شیطان، زہریلے جانور اور بری نظر سے۔", "मैं अल्लाह के कामिल कलिमात की पनाह माँगता हूँ हर शैतान, ज़हरीले जानवर और बुरी नज़र से।", "আমি আল্লাহর পরিপূর্ণ কালিমার আশ্রয় চাই প্রতিটি শয়তান, বিষধর প্রাণী ও বদনজর থেকে।", "Aku berlindung dengan kalimat Allah yang sempurna dari setiap setan, binatang berbisa, dan mata yang jahat."),
    "whisper": ("I seek refuge in Allah, the All-Hearing, All-Knowing, from Satan the accursed.", "میں سننے والے جاننے والے اللہ کی پناہ مانگتا ہوں شیطان مردود سے۔", "मैं सुनने वाले जानने वाले अल्लाह की पनाह माँगता हूँ शापित शैतान से।", "আমি সর্বশ্রোতা সর্বজ্ঞ আল্লাহর আশ্রয় চাই অভিশপ্ত শয়তান থেকে।", "Aku berlindung kepada Allah Yang Maha Mendengar Maha Mengetahui dari setan yang terkutuk."),
    "market": ("There is no god but Allah, alone without partner. His is the dominion and His is the praise. He gives life and causes death, and He is Ever-Living and does not die. In His hand is all good, and He is over all things competent.", "اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے اس کا کوئی شریک نہیں، اسی کی بادشاہی ہے اور اسی کی تعریف، وہ جِلاتا اور مارتا ہے، وہ ہمیشہ زندہ ہے جو نہیں مرتا، اس کے ہاتھ میں ساری بھलाई ہے اور وہ ہر چیز پر قادر ہے۔", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है बिना साझी के, उसी की बादशाही और हम्द है, वह जिलाता और मारता है, वह हमेशा ज़िंदा है जो नहीं मरता।", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক অংশীদারহীন, রাজত্ব ও প্রশংসা তাঁর, তিনি জীবন দেন ও মৃত্যু দেন, তিনি চিরঞ্জীব মরেন না।", "Tiada tuhan selain Allah Yang Esa tanpa sekutu. Milik-Nya kerajaan dan pujian. Dia menghidupkan dan mematikan, Maha Hidup dan tidak mati. Di tangan-Nya segala kebaikan, dan Dia Mahakuasa atas segala sesuatu."),
    "new-year": ("O Allah, bless us in Rajab and Sha'ban, and let us reach Ramadan.", "اے اللہ! رجب اور شعبان میں ہمیں برکت دے، اور ہمیں رمضان تک پہنچا دے۔", "ऐ अल्लाह! रजब और शाबान में हमें बरकत दे, और हमें रमज़ान तक पहुँचा दे।", "হে আল্লাহ, রজব ও শাবানে আমাদের বরকত দাও, আর আমাদের রমজান পর্যন্ত পৌঁছাও।", "Ya Allah, berkahilah kami di Rajab dan Syaban, dan sampaikan kami kepada Ramadan."),
    "friday": ("O Allah, send blessings upon Muhammad and upon the family of Muhammad.", "اے اللہ! محمد اور آل محمد پر رحمت بھیج۔", "ऐ अल्लाह! मुहम्मद और आले मुहम्मद पर रहमत भेज।", "হে আল্লাহ, মুহাম্মদ ও তাঁর পরিবারের প্রতি রহমত পাঠাও।", "Ya Allah, limpahkan shalawat kepada Muhammad dan keluarga Muhammad."),
    "entering-gathering": ("My Lord, forgive me and accept my repentance. Indeed You are the Accepting of repentance, the Merciful.", "اے میرے رب! مجھے بخش دے اور میری توبہ قبول فرما، بے شک تو توبہ قبول کرنے والا مہربان ہے۔", "ऐ मेरे रब! मुझे बख़्श दे और मेरी तौबा क़ुबूल फ़रमा, यक़ीनन तू तौबा क़ुबूल करने वाला मेहरबान है।", "হে আমার রব, আমাকে ক্ষমা করো ও তওবা কবুল করো, নিশ্চয় তুমি তওবা কবুলকারী দয়ালু।", "Tuhanku, ampunilah aku dan terimalah tobatku. Sungguh Engkau Maha Penerima tobat lagi Maha Penyayang."),
    "leaving-gathering": ("Glory and praise be to You, O Allah. I bear witness that there is no god but You. I seek Your forgiveness and repent to You.", "اے اللہ! تو پاک ہے اور تیری حمد ہے، میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں، میں تجھ سے بخشش مانگتا ہوں اور تیری طرف توبہ کرتا ہوں۔", "ऐ अल्लाह! तू पाक है और तेरी हम्द है, मैं गवाही देता हूँ कि तेरे सिवा कोई माबूद नहीं, मैं तुझसे बख़्शिश माँगता हूँ और तेरी तरफ़ तौबा करता हूँ।", "হে আল্লাহ, তুমি পবিত্র ও প্রশংসিত, আমি সাক্ষ্য দিই তুমি ছাড়া কোনো ইলাহ নেই, আমি ক্ষমা চাই ও তওবা করি।", "Mahasuci Engkau, ya Allah, dan dengan memuji-Mu. Aku bersaksi tiada tuhan selain Engkau. Aku memohon ampun dan bertaubat kepada-Mu."),
    "seeing-afflicted": ("Praise be to Allah Who spared me from what He has tested you with, and Who favored me greatly over many of those He created.", "تمام تعریفیں اس اللہ کے لیے جس نے مجھے اس سے بچایا جس میں تجھے مبتلا کیا، اور مجھے بہتوں پر فضیلت دی۔", "सारी हम्द अल्लाह के लिए जिसने मुझे उससे बचाया जिसमें तुझे मुब्तला किया, और मुझे बहुतों पर फ़ज़ीलत दी।", "সমস্ত প্রশংসা আল্লাহর, যিনি তোমাকে যা দিয়ে পরীক্ষা করেছেন তা থেকে আমাকে রক্ষা করেছেন।", "Segala puji bagi Allah yang menyelamatkanku dari ujian yang menimpamu, dan yang melebihkanku atas banyak makhluk-Nya."),
    "hearing-rooster": ("O Allah, I ask You of Your bounty.", "اے اللہ! میں تجھ سے تیرا فضل مانگتا ہوں۔", "ऐ अल्लाह! मैं तुझसे तेरा फ़ज़्ल माँगता हूँ।", "হে আল্লাহ, আমি তোমার অনুগ্রহ চাই।", "Ya Allah, aku memohon karunia-Mu."),
    "hearing-donkey": ("I seek refuge in Allah from Satan, the accursed.", "میں اللہ کی پناহ مانگتا ہوں شیطان مردود سے۔", "मैं अल्लाह की पनाह माँगता हूँ शापित शैतान से।", "আমি অভিশপ্ত শয়তান থেকে আল্লাহর আশ্রয় চাই।", "Aku berlindung kepada Allah dari setan yang terkutuk."),
    "new-moon": ("O Allah, bring it over us with blessing and faith, safety and Islam.", "اے اللہ! اسے ہم پر یمن، ایمان، سلامتی اور اسلام کے ساتھ طلوع فرما۔", "ऐ अल्लाह! इसे हम पर युम्न, ईमान, सलामती और इस्लाम के साथ तुलू फ़रमा।", "হে আল্লাহ, এটিকে আমাদের উপর কল্যাণ, ঈমান, নিরাপত্তা ও ইসলামসহ উদিত করো।", "Ya Allah, tampakkan ia atas kami dengan keberkahan, iman, keselamatan, dan Islam."),
    "after-rain": ("We have been given rain by the bounty and mercy of Allah.", "ہمیں اللہ کے فضل اور رحمت سے بارش ملی۔", "हमें अल्लाह के फ़ज़्ल और रहमत से बारिश मिली।", "আমরা আল্লাহর অনুগ্রহ ও রহমতে বৃষ্টি পেয়েছি।", "Kami diberi hujan dengan karunia dan rahmat Allah."),
    "distress": ("There is no god but Allah, the Magnificent, the Forbearing. There is no god but Allah, Lord of the Mighty Throne.", "اللہ کے سوا کوئی معبود نہیں جو عظمت والا بردبار ہے، اللہ کے سوا کوئی معبود نہیں جو عرش عظیم کا رب ہے۔", "अल्लाह के सिवा कोई माबूद नहीं जो अज़मत वाला हलिम है, अल्लाह के सिवा कोई माबूद नहीं जो अर्श-ए-अज़ीम का रब है।", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি মহান সহনশীল; আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি মহান আরশের রব।", "Tiada tuhan selain Allah Yang Mahaagung lagi Maha Penyantun. Tiada tuhan selain Allah, Tuhan Arasy yang agung."),
    "guidance": ("Our Lord, do not let our hearts deviate after You have guided us, and grant us mercy from Yourself.", "اے ہمارے رب! ہدایت دینے کے بعد ہمارے دلوں کو ٹیڑھا نہ کر، اور اپنی طرف سے ہمیں رحمت عطا فرما۔", "ऐ हमारे रब! हिदायत देने के बाद हमारे दिलों को टेढ़ा न कर, और अपनी तरफ़ से हमें रहमत अता फ़रमा।", "হে আমাদের রব, হিদায়াত দেওয়ার পর আমাদের অন্তর বাঁকা কোরো না, আর নিজের কাছ থেকে রহমত দাও।", "Tuhan kami, jangan condongkan hati kami setelah Engkau beri petunjuk, dan anugerahkan rahmat dari sisi-Mu."),
    "forgiveness": ("My Lord, forgive me and accept my repentance. Indeed You are the Accepting of repentance, the Merciful.", "اے میرے رب! مجھے بخش دے اور میری توبہ قبول فرما، بے شک تو توبہ قبول کرنے والا مہربان ہے۔", "ऐ मेरे रब! मुझे बख़्श दे और मेरी तौबा क़ुबूल फ़रमा।", "হে আমার রব, আমাকে ক্ষমা করো ও তওবা কবুল করো।", "Tuhanku, ampunilah aku dan terimalah tobatku. Sungguh Engkau Maha Penerima tobat lagi Maha Penyayang."),
    "jannah": ("Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.", "اے ہمارے رب! ہمیں دنیا میں بھلائی دے اور آخرت میں بھلائی، اور آگ کے عذاب سے بچا۔", "ऐ हमारे रब! हमें दुनिया में भलाई दे और आख़िरत में भलाई, और आग के अज़ाब से बचा।", "হে আমাদের রব, দুনিয়ায় কল্যাণ দাও ও আখিরাতে কল্যাণ দাও, আর আগুনের আজাব থেকে রক্ষা করো।", "Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami dari azab neraka."),
    "death": ("O Allah, keep me alive as long as life is better for me, and take me when death is better for me.", "اے اللہ! مجھے اس وقت تک زندہ رکھ جب تک زندگی میرے لیے بہتر ہے، اور جب موت بہتر ہو تو اٹھا لے۔", "ऐ अल्लाह! मुझे तब तक ज़िंदा रख जब तक ज़िंदगी मेरे लिए बेहतर है, और जब मौत बेहतर हो तो उठा ले।", "হে আল্লাহ, যতক্ষণ জীবন আমার জন্য উত্তম ততক্ষণ বাঁচিয়ে রাখো, আর মৃত্যু উত্তম হলে তুলে নাও।", "Ya Allah, hidupkan aku selama hidup lebih baik bagiku, dan wafatkan aku jika kematian lebih baik bagiku."),
    "grave": ("O Allah, I seek refuge in You from the punishment of the grave.", "اے اللہ! میں قبر کے عذاب سے تیری پناہ مانگتا ہوں۔", "ऐ अल्लाह! मैं क़ब्र के अज़ाब से तेरी पनाह माँगता हूँ।", "হে আল্লাহ, আমি কবরের আজাব থেকে তোমার আশ্রয় চাই।", "Ya Allah, aku berlindung kepada-Mu dari azab kubur."),
    "dajjal": ("O Allah, I seek refuge in You from the trial of the False Messiah.", "اے اللہ! میں دجال مسیح کے فتنے سے تیری پناہ مانگتا ہوں۔", "ऐ अल्लाह! मैं दज्जाल मसीह के फ़ितने से तेरी पनाह माँगता हूँ।", "হে আল্লাহ, আমি দাজ্জালের ফিতনা থেকে তোমার আশ্রয় চাই।", "Ya Allah, aku berlindung kepada-Mu dari fitnah Al-Masih Ad-Dajjal."),
    "morning": ("O Allah, by You we enter the morning, by You we enter the evening, by You we live, by You we die, and to You is the resurrection.", "اے اللہ! تیری توفیق سے ہم نے صبح کی، تیری توفیق سے شام کی، تیرے ساتھ جیتے ہیں، تیرے ساتھ مرتے ہیں، اور تیری طرف اٹھنا ہے۔", "ऐ अल्लाह! तेरी तौफ़ीक़ से हमने सुबह की, शाम की, तेरे साथ जीते हैं, मरते हैं, और तेरी तरफ़ उठना है।", "হে আল্লাহ, তোমার দিয়ে আমরা সকাল করি, সন্ধ্যা করি, বাঁচি, মরি, আর তোমার দিকেই পুনরুত্থান।", "Ya Allah, dengan-Mu kami memasuki pagi, dengan-Mu kami memasuki petang, dengan-Mu kami hidup, dengan-Mu kami mati, dan kepada-Mu kebangkitan."),
    "evening": ("O Allah, by You we enter the evening, by You we enter the morning, by You we live, by You we die, and to You is the return.", "اے اللہ! تیری توفیق سے ہم نے شام کی، تیری توفیق سے صبح کی، تیرے ساتھ جیتے ہیں، تیرے ساتھ مرتے ہیں، اور تیری طرف لوٹنا ہے۔", "ऐ अल्लाह! तेरी तौफ़ीक़ से हमने शाम की, सुबह की, तेरे साथ जीते हैं, मरते हैं, और तेरी तरफ़ लौटना है।", "হে আল্লাহ, তোমার দিয়ে আমরা সন্ধ্যা করি, সকাল করি, বাঁচি, মরি, আর তোমার দিকেই প্রত্যাবর্তন।", "Ya Allah, dengan-Mu kami memasuki petang, dengan-Mu kami memasuki pagi, dengan-Mu kami hidup, dengan-Mu kami mati, dan kepada-Mu tempat kembali."),
    "ayatul-kursi-intent": ("Allah — there is no god except Him, the Ever-Living, the Sustainer of existence.", "اللہ — اس کے سوا کوئی معبود نہیں، وہ ہمیشہ زندہ سب کا تھامنے والا ہے۔", "अल्लाह — उसके सिवा कोई माबूद नहीं, वह हमेशा ज़िंदा सबका थामने वाला है।", "আল্লাহ — তিনি ছাড়া কোনো ইলাহ নেই, তিনি চিরঞ্জীব, সৃষ্টির ধারক।", "Allah, tidak ada tuhan selain Dia, Yang Maha Hidup, Maha Berdiri sendiri."),
    "last-two-surahs": ("Say: I seek refuge in the Lord of daybreak.", "کہو: میں صبح کے رب کی پناہ مانگتا ہوں۔", "कहो: मैं सुबह के रब की पनाह माँगता हूँ।", "বলো: আমি প্রভাতের রবের আশ্রয় চাই।", "Katakanlah: aku berlindung kepada Tuhan yang menguasai subuh."),
    "ikhlas": ("Say: He is Allah, the One.", "کہو: وہ اللہ ایک ہے۔", "कहो: वह अल्लाह एक है।", "বলো: তিনি আল্লাহ, একক।", "Katakanlah: Dia-lah Allah, Yang Maha Esa."),
    "istiadha": ("I seek refuge in Allah from Satan, the accursed.", "میں اللہ کی پناہ مانگتا ہوں شیطان مردود سے۔", "मैं अल्लाह की पनाह माँगता हूँ शापित शैतान से।", "আমি অভিশপ্ত শয়তান থেকে আল্লাহর আশ্রয় চাই।", "Aku berlindung kepada Allah dari setan yang terkutuk."),
    "basmala": ("In the name of Allah, the Entirely Merciful, the Especially Merciful.", "اللہ کے نام سے جو نہایت مہربان بہت رحم والا ہے۔", "अल्लाह के नाम से जो निहायत मेहरबान बहुत रहम वाला है।", "পরম করুণাময় অসীম দয়ালু আল্লাহর নামে।", "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang."),
    "thanking-someone": ("May Allah reward you with good.", "اللہ تمہیں بہتر بدلہ دے۔", "अल्लाह तुम्हें बेहतर बदला दे।", "আল্লাহ তোমাকে উত্তম প্রতিদান দিন।", "Semoga Allah membalasmu dengan kebaikan."),
    "reply-thank": ("And you; may Allah bless you.", "اور تمہیں بھی، اللہ تم میں برکت دے۔", "और तुम्हें भी, अल्लाह तुम में बरकत दे।", "আর তোমাকেও, আল্লাহ তোমায় বরকত দিন।", "Dan engkau juga; semoga Allah memberkahimu."),
    "wedding": ("May Allah bless you, send blessings upon you, and join you both in goodness.", "اللہ تمہیں برکت دے، تم پر برکت نازل فرمائے، اور تم دونوں کو خیر میں جمع کرے۔", "अल्लाह तुम्हें बरकत दे, तुम पर बरकत नाज़िल फ़रमाए, और तुम दोनों को ख़ैर में जमा करे।", "আল্লাহ তোমায় বরকত দিন, তোমার উপর বরকত নাজিল করুন, আর তোমাদের কল্যাণে একত্র করুন।", "Semoga Allah memberkahimu, menurunkan berkah atasmu, dan mengumpulkan kalian berdua dalam kebaikan."),
    "newborn": ("I seek protection for him in the perfect words of Allah from every devil, poisonous creature, and evil eye.", "میں اسے اللہ کے کامل کلمات کی پناہ میں دیتا ہوں ہر شیطان، زہریلے جانور اور بری نظر سے۔", "मैं उसे अल्लाह के कामिल कलिमात की पनाह में देता हूँ हर शैतान, ज़हरीले जानवर और बुरी नज़र से।", "আমি তাকে আল্লাহর পরিপূর্ণ কালিমার আশ্রয়ে রাখি প্রতিটি শয়তান, বিষধর প্রাণী ও বদনজর থেকে।", "Aku mohon perlindungan baginya dengan kalimat Allah yang sempurna dari setiap setan, binatang berbisa, dan mata yang jahat."),
    "aqiqah-intent": ("O Allah, this is from You and for You.", "اے اللہ! یہ تیری طرف سے ہے اور تیرے لیے ہے۔", "ऐ अल्लाह! यह तेरी तरफ़ से है और तेरे लिए है।", "হে আল্লাহ, এটি তোমার কাছ থেকে এবং তোমার জন্য।", "Ya Allah, ini dari-Mu dan untuk-Mu."),
    "janazah": ("O Allah, forgive him and have mercy on him, grant him well-being and pardon him.", "اے اللہ! اسے بخش دے اور اس پر رحم فرما، اسے عافیت دے اور اسے معاف فرما دے۔", "ऐ अल्लाह! उसे बख़्श दे और उस पर रहम फ़रमा, उसे आफ़ियत दे और उसे माफ़ फ़रमा दे।", "হে আল্লাহ, তাকে ক্ষমা করো ও দয়া করো, সুস্থতা দাও ও মাফ করো।", "Ya Allah, ampunilah dia dan rahmatilah, sejahterakan dan maafkan dia."),
    "visiting-grave": ("Peace be upon you, O people of the dwellings, believers and Muslims. Indeed we, if Allah wills, will join you.", "اے مومنو اور مسلمانو جو ان گھروں میں ہو، تم پر سلامتی ہو، اور ہم ان شاء اللہ تم سے ملنے والے ہیں۔", "ऐ मोमिनो और मुसलमानो जो इन घरों में हो, तुम पर सलामती हो, और हम इंशाअल्लाह तुमसे मिलने वाले हैं।", "হে মুমিন ও মুসলিম অধিবাসীগণ, তোমাদের উপর শান্তি, আর আমরা ইনশাআল্লাহ তোমাদের সঙ্গে মিলিত হব।", "Salam atasmu, wahai penghuni negeri, orang-orang mukmin dan muslim. Sungguh kami, insya Allah, akan menyusulmu."),
    "after-wudu-extra": ("O Allah, make me among those who repent and make me among those who purify themselves.", "اے اللہ! مجھے توبہ کرنے والوں میں اور پاکیزگی اختیار کرنے والوں میں بنا دے۔", "ऐ अल्लाह! मुझे तौबा करने वालों में और पाकीज़गी अपनाने वालों में बना दे।", "হে আল্লাহ, আমাকে তওবাকারী ও পবিত্রতা অবলম্বনকারীদের অন্তর্ভুক্ত করো।", "Ya Allah, jadikan aku termasuk orang yang bertaubat dan orang yang menyucikan diri."),
    "before-wudu-niyyah": ("I intend ablution to lift impurity, for the sake of Allah the Exalted.", "میں نے حدث دور کرنے کے لیے اللہ تعالیٰ کے لیے وضو کی نیت کی۔", "मैंने हदस दूर करने के लिए अल्लाह तआला के लिए वुज़ू की नीयत की।", "আল্লাহ তাআলার জন্য অপবিত্রতা দূর করতে ওজুর নিয়ত করলাম।", "Aku niat wudu untuk menghilangkan hadas karena Allah Ta'ala."),
    "leaving-home-long": ("O Allah, I seek refuge in You from going astray or being led astray, from slipping or being caused to slip, from wronging or being wronged, from acting ignorantly or being treated ignorantly.", "اے اللہ! میں گمراہ ہونے یا گمراہ کیے جانے، پھسلنے یا پھسلائے جانے، ظلم کرنے یا مظلوم ہونے، جہالت کرنے یا جہالت کا نشانہ بننے سے تیری پناہ مانگتا ہوں۔", "ऐ अल्लाह! मैं गुमराह होने या गुमराह किए जाने, फिसलने या फिसलाए जाने से तेरी पनाह माँगता हूँ।", "হে আল্লাহ, পথভ্রষ্ট হওয়া বা হওয়া, পিছলে পড়া, জুলুম করা বা হওয়া থেকে তোমার আশ্রয় চাই।", "Ya Allah, aku berlindung kepada-Mu dari tersesat atau disesatkan, tergelincir atau digelincirkan, menzalimi atau dizalimi, berlaku bodoh atau dibodohi."),
    "mounting": ("In the name of Allah, praise be to Allah. Glory be to Him Who subjected this to us.", "اللہ کے نام سے، تمام تعریفیں اللہ کے لیے ہیں، پاک ہے وہ جس نے اسے ہمارے لیے مسخر کیا۔", "अल्लाह के नाम से, सारी हम्द अल्लाह के लिए है, पाक है वह जिसने इसे हमारे वश में किया।", "আল্লাহর নামে, সমস্ত প্রশংসা আল্লাহর, পবিত্র তিনি যিনি এটিকে আমাদের অধীন করেছেন।", "Dengan nama Allah, segala puji bagi Allah. Mahasuci Dia yang menundukkan ini bagi kami."),
    "on-return-home": ("Repenting, returning to our Lord, leaving no sin upon us.", "توبہ کرتے ہوئے اپنے رب کی طرف لوٹتے ہیں، کوئی گناہ ہم پر باقی نہ رہے۔", "तौबा करते हुए अपने रब की तरफ़ लौटते हैं, कोई गुनाह हम पर बाक़ी न रहे।", "তওবা করে আমাদের রবের দিকে ফিরি, কোনো গুনাহ আমাদের উপর না থাকুক।", "Bertaubat, kembali kepada Tuhan kami, tidak menyisakan dosa atas kami."),
    "seeing-something-pleasing": ("Praise be to Allah, by Whose blessing good things are completed.", "تمام تعریفیں اس اللہ کے لیے جس کی نعمت سے نیک کام پورے ہوتے ہیں۔", "सारी हम्द उस अल्लाह के लिए जिसकी नेमत से नेक काम पूरे होते हैं।", "সমস্ত প্রশংসা আল্লাহর, যাঁর নিয়ামতে সৎকাজ সম্পূর্ণ হয়।", "Segala puji bagi Allah yang dengan nikmat-Nya kebaikan menjadi sempurna."),
    "seeing-something-displeasing": ("Praise be to Allah in every circumstance.", "ہر حال میں تمام تعریفیں اللہ کے لیے ہیں۔", "हर हाल में सारी हम्द अल्लाह के लिए है।", "প্রতি অবস্থায় সমস্ত প্রশংসা আল্লাহর।", "Segala puji bagi Allah dalam setiap keadaan."),
    "wearing-ihram": ("Here I am, O Allah, here I am. Here I am, You have no partner, here I am.", "میں حاضر ہوں اے اللہ! میں حاضر ہوں، تیرا کوئی شریک نہیں، میں حاضر ہوں۔", "मैं हाज़िर हूँ ऐ अल्लाह! मैं हाज़िर हूँ, तेरा कोई शरीक नहीं, मैं हाज़िर हूँ।", "আমি হাজির হে আল্লাহ, আমি হাজির, তোমার কোনো শরিক নেই, আমি হাজির।", "Aku penuhi panggilan-Mu, ya Allah. Aku penuhi panggilan-Mu, tiada sekutu bagi-Mu."),
    "tawaf": ("Our Lord, give us good in this world and good in the Hereafter, and protect us from the Fire.", "اے ہمارے رب! ہمیں دنیا میں بھلائی دے اور آخرت میں بھلائی، اور آگ سے بچا۔", "ऐ हमारे रब! हमें दुनिया में भलाई दे और आख़िरत में भलाई, और आग से बचा।", "হে আমাদের রব, দুনিয়ায় কল্যাণ ও আখিরাতে কল্যাণ দাও, আর আগুন থেকে রক্ষা করো।", "Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami dari neraka."),
    "safa-marwa": ("Indeed, Safa and Marwah are among the symbols of Allah.", "بے شک صفا اور مروہ اللہ کی نشانیوں میں سے ہیں۔", "यक़ीनन सफ़ा और मरवा अल्लाह की निशानियों में से हैं।", "নিশ্চয় সাফা ও মারওয়া আল্লাহর নিদর্শনসমূহের অন্তর্ভুক্ত।", "Sungguh Safa dan Marwah termasuk syiar-syiar Allah."),
    "arrafat": ("There is no god but Allah, alone without partner. His is the dominion and His is the praise, and He is over all things competent.", "اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے اس کا کوئی شریک نہیں، اسی کی بادشاہی ہے اور اسی کی تعریف، اور وہ ہر چیز پر قادر ہے۔", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है बिना साझी के, उसी की बादशाही और हम्द है, और वह हर चीज़ पर क़ादिर है।", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক অংশীদারহীন, রাজত্ব ও প্রশংসা তাঁর, তিনি সব কিছুর উপর ক্ষমতাবান।", "Tiada tuhan selain Allah Yang Esa tanpa sekutu. Milik-Nya kerajaan dan pujian, dan Dia Mahakuasa atas segala sesuatu."),
    "after-sadaqah": ("O Allah, accept from us. Indeed You are the All-Hearing, All-Knowing.", "اے اللہ! ہم سے قبول فرما، بے شک تو سننے والا جاننے والا ہے۔", "ऐ अल्लाह! हमसे क़ुबूल फ़रमा, यक़ीनन तू सुनने वाला जानने वाला है।", "হে আল্লাহ, আমাদের থেকে কবুল করো, নিশ্চয় তুমি সর্বশ্রোতা সর্বজ্ঞ।", "Ya Allah, terimalah dari kami. Sungguh Engkau Maha Mendengar Maha Mengetahui."),
    "before-study": ("My Lord, expand my chest for me, make my task easy, and untie the knot from my tongue.", "اے میرے رب! میرا سینہ کھول دے، میرا کام آسان کر دے، اور میری زبان کی گرہ کھول دے۔", "ऐ मेरे रब! मेरा सीना खोल दे, मेरा काम आसान कर दे, और मेरी ज़बान की गिरह खोल दे।", "হে আমার রব, আমার বক্ষ প্রশস্ত করো, কাজ সহজ করো, আর জিহ্বার গ্রন্থি খুলে দাও।", "Tuhanku, lapangkanlah dadaku, mudahkan urusanku, dan lepaskan ikatan dari lidahku."),
    "after-study": ("O Allah, benefit me by what You have taught me, and teach me what will benefit me.", "اے اللہ! جو تو نے مجھے سکھایا اس سے مجھے نفع دے، اور مجھے وہ سکھا جو میرے لیے نفع بخش ہو۔", "ऐ अल्लाह! जो तूने मुझे सिखाया उससे मुझे नफ़ा दे, और मुझे वह सिखा जो मेरे लिए नफ़ेमंद हो।", "হে আল্লাহ, যা শিখিয়েছ তা দিয়ে উপকৃত করো, আর যা উপকারী তা শেখাও।", "Ya Allah, berilah manfaat dengan apa yang Engkau ajarkan kepadaku, dan ajarkan apa yang bermanfaat bagiku."),
    "ease": ("O Allah, there is no ease except what You make easy, and You make the difficult easy if You will.", "اے اللہ! وہی آسان ہے جو تو آسان کرے، اور تو چاہے تو مشکل کو آسان کر دیتا ہے۔", "ऐ अल्लाह! वही आसान है जो तू आसान करे, और तू चाहे तो मुश्किल को आसान कर देता है।", "হে আল্লাহ, তুমি যা সহজ করো তা ছাড়া সহজ নেই, আর তুমি চাইলে কঠিনকে সহজ করো।", "Ya Allah, tidak ada kemudahan kecuali yang Engkau mudahkan, dan Engkau menjadikan yang sulit menjadi mudah jika Engkau kehendaki."),
    "taqwa": ("O Allah, I ask You for guidance, piety, chastity, and self-sufficiency.", "اے اللہ! میں تجھ سے ہدایت، تقویٰ، پاکدامنی اور بے نیازی مانگتا ہوں۔", "ऐ अल्लाह! मैं तुझसे हिदायत, तक़वा, पाकदामनी और बेनियाज़ी माँगता हूँ।", "হে আল্লাহ, আমি হিদায়াত, তাকওয়া, পবিত্রতা ও অভাবমুক্তি চাই।", "Ya Allah, aku memohon petunjuk, takwa, kesucian, dan kecukupan."),
    "good-character": ("O Allah, as You have made my form good, make my character good.", "اے اللہ! جیسے تو نے میری صورت کو اچھا بنایا، میرے اخلاق کو بھی اچھا بنا دے۔", "ऐ अल्लाह! जैसे तूने मेरी सूरत अच्छी बनाई, मेरे अख़लाक़ भी अच्छे बना दे।", "হে আল্লাহ, যেমন তুমি আমার আকৃতি ভালো করেছ, আমার চরিত্রও ভালো করো।", "Ya Allah, sebagaimana Engkau baguskan bentukku, baguskan pula akhlakku."),
    "sincerity": ("O Allah, make all my deeds righteous and make them sincerely for Your sake.", "اے اللہ! میرے سارے اعمال نیک بنا دے، اور انہیں اپنی رضا کے لیے خالص کر دے۔", "ऐ अल्लाह! मेरे सारे अमाल नेक बना दे, और उन्हें अपनी रज़ा के लिए ख़ालिस कर दे।", "হে আল্লাহ, আমার সব আমল সৎ করো এবং তোমার সন্তুষ্টির জন্য নিখাদ করো।", "Ya Allah, jadikan seluruh amalku saleh dan ikhlas karena wajah-Mu."),
    "ummah": ("O Allah, rectify the Ummah of Muhammad.", "اے اللہ! محمد کی امت کی اصلاح فرما۔", "ऐ अल्लाह! मुहम्मद की उम्मत की इस्लाह फ़रमा।", "হে আল্লাহ, মুহাম্মদের উম্মাহর সংশোধন করো।", "Ya Allah, perbaikilah umat Muhammad."),
    "palestine": ("O Allah, be a helper for the oppressed.", "اے اللہ! مظلوموں کا مددگار بن جا۔", "ऐ अल्लाह! मज़लूमों का मददगार बन जा।", "হে আল্লাহ, মজলুমদের সাহায্যকারী হও।", "Ya Allah, jadilah penolong bagi orang-orang yang tertindas."),
    "rain-stop": ("O Allah, around us and not upon us.", "اے اللہ! ہمارے آس پاس برسا، ہم پر نہیں۔", "ऐ अल्लाह! हमारे आसपास बरसा, हम पर नहीं।", "হে আল্লাহ, আমাদের চারপাশে বর্ষাও, আমাদের উপর নয়।", "Ya Allah, di sekitar kami dan jangan menimpa kami."),
    "entering-market-short": ("There is no god but Allah, alone, without partner.", "اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں۔", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं।", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই।", "Tiada tuhan selain Allah Yang Esa tanpa sekutu."),
    "after-eating-short": ("Praise be to Allah.", "تمام تعریفیں اللہ کے لیے ہیں۔", "सारी प्रशंसा अल्लाह के लिए है।", "সমস্ত প্রশংসা আল্লাহর।", "Segala puji bagi Allah."),
    "when-in-pain": ("I seek refuge in Allah and His power from the evil of what I feel and fear.", "میں اللہ اور اس کی قدرت کی پناہ مانگتا ہوں اس شر سے جو میں محسوس کرتا ہوں اور جس سے ڈرتا ہوں۔", "मैं अल्लाह और उसकी क़ुदरत की पनाह माँगता हूँ उस शर से जो मैं महसूस करता हूँ और जिससे डरता हूँ।", "আমি আল্লাহ ও তাঁর কুদরতের আশ্রয় চাই যা অনুভব করি ও যা ভয় করি তার অনিষ্ট থেকে।", "Aku berlindung kepada Allah dan kekuasaan-Nya dari keburukan yang aku rasakan dan aku takuti."),
    "before-sleep-ayat": ("Allah — there is no god except Him, the Ever-Living, the Sustainer. Neither drowsiness nor sleep overtakes Him.", "اللہ — اس کے سوا کوئی معبود نہیں، وہ ہمیشہ زندہ قائم ہے، اسے نہ اونگھ آتی ہے نہ نیند۔", "अल्लाह — उसके सिवा कोई माबूद नहीं, वह हमेशा ज़िंदा क़ायम है, उसे न ऊँघ आती है न नींद।", "আল্লাহ — তিনি ছাড়া কোনো ইলাহ নেই, তিনি চিরঞ্জীব স্থায়ী, তাঁকে তন্দ্রাও স্পর্শ করে না নিদ্রাও নয়।", "Allah, tidak ada tuhan selain Dia, Yang Maha Hidup lagi Maha Berdiri sendiri. Tidak mengantuk dan tidak tidur."),
    "on-waking-night": ("There is no god but Allah, alone without partner. His is the dominion and His is the praise, and He is over all things competent.", "اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے اس کا کوئی شریک نہیں، اسی کی بادشاہی ہے اور اسی کی تعریف، اور وہ ہر چیز پر قادر ہے۔", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है बिना साझी के, उसी की बादशाही और हम्द है।", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক অংশীদারহীন, রাজত্ব ও প্রশংসা তাঁর।", "Tiada tuhan selain Allah Yang Esa tanpa sekutu. Milik-Nya kerajaan dan pujian, dan Dia Mahakuasa atas segala sesuatu."),
    "istighfar-sayyid": ("O Allah, You are my Lord; there is no god but You. You created me and I am Your servant, and I am upon Your covenant and promise as much as I am able.", "اے اللہ! تو میرا رب ہے، تیرے سوا کوئی معبود نہیں، تو نے مجھے پیدا کیا اور میں تیرا بندہ ہوں، اور میں اپنی استطاعت کے مطابق تیرے عہد اور وعدے پر قائم ہوں۔", "ऐ अल्लाह! तू मेरा रब है, तेरे सिवा कोई माबूद नहीं, तूने मुझे पैदा किया और मैं तेरा बंदा हूँ।", "হে আল্লাহ, তুমি আমার রব, তুমি ছাড়া কোনো ইলাহ নেই, তুমি আমাকে সৃষ্টি করেছ আর আমি তোমার বান্দা।", "Ya Allah, Engkau Tuhanku, tiada tuhan selain Engkau. Engkau menciptakanku dan aku hamba-Mu, dan aku berada di atas perjanjian dan janji-Mu semampuku."),
    "for-deceased-child": ("O Allah, make him a forerunner and a treasure for his parents.", "اے اللہ! اسے اس کے والدین کے لیے آگے بھیجا ہوا ذخیرہ بنا دے۔", "ऐ अल्लाह! उसे उसके वालिदैन के लिए आगे भेजा हुआ ज़ख़ीरा बना दे।", "হে আল্লাহ, তাকে তার পিতা-মাতার জন্য অগ্রগামী সঞ্চয় বানাও।", "Ya Allah, jadikan dia pelopor dan simpanan bagi kedua orang tuanya."),
    "after-salam-33": ("Glory be to Allah, praise be to Allah, Allah is the Greatest.", "اللہ پاک ہے، تمام تعریفیں اللہ کے لیے ہیں، اللہ سب سے بڑا ہے۔", "अल्लाह पाक है, सारी हम्द अल्लाह के लिए है, अल्लाह सबसे बड़ा है।", "আল্লাহ পবিত্র, সমস্ত প্রশংসা আল্লাহর, আল্লাহ সর্বশ্রেষ্ঠ।", "Mahasuci Allah, segala puji bagi Allah, Allah Mahabesar."),
    "entering-bathroom-long": ("In the name of Allah. O Allah, I seek refuge in You from the male and female unclean spirits.", "اللہ کے نام سے۔ اے اللہ! میں ناپاک نر و مادہ جنّات سے تیری پناہ مانگتا ہوں۔", "अल्लाह के नाम से। ऐ अल्लाह! मैं नर और मादा नापाक जिन्नों से तेरी पनाह माँगता हूँ।", "আল্লাহর নামে। হে আল্লাহ, নর-নারী অপবিত্র জিন থেকে তোমার আশ্রয় চাই।", "Dengan nama Allah. Ya Allah, aku berlindung kepada-Mu dari setan laki-laki dan perempuan."),
    "on-hearing-good-news": ("Praise be to Allah, by Whose blessing righteous affairs are completed.", "تمام تعریفیں اس اللہ کے لیے جس کی نعمت سے نیک کام پورے ہوتے ہیں۔", "सारी हम्द उस अल्लाह के लिए जिसकी नेमत से नेक काम पूरे होते हैं।", "সমস্ত প্রশংসা আল্লাহর, যাঁর নিয়ামতে সৎকাজ সম্পূর্ণ হয়।", "Segala puji bagi Allah yang dengan nikmat-Nya urusan yang baik menjadi sempurna."),
    "when-given-gift": ("May Allah bless you in your family and your wealth.", "اللہ تمہارے گھر والوں اور مال میں برکت دے۔", "अल्लाह तुम्हारे घर वालों और माल में बरकत दे।", "আল্লাহ তোমার পরিবার ও সম্পদে বরকত দিন।", "Semoga Allah memberkahimu pada keluarga dan hartamu."),
    "before-meal-host": ("O Allah, feed the one who has fed me, and give drink to the one who has given me drink.", "اے اللہ! جس نے مجھے کھلایا اسے کھلا، اور جس نے مجھے پلایا اسے پلا۔", "ऐ अल्लाह! जिसने मुझे खिलाया उसे खिला, और जिसने मुझे पिलाया उसे पिला।", "হে আল্লাহ, যে আমাকে খাইয়েছে তাকে খাওয়াও, যে পান করিয়েছে তাকে পান করাও।", "Ya Allah, berilah makan orang yang memberiku makan, dan berilah minum orang yang memberiku minum."),
}


def localized_title(dua_id, roman_fallback):
    parts = TITLES.get(dua_id)
    if not parts:
        return _pack(("", "", "", "", ""), roman_fallback)
    return _pack(parts, roman_fallback)


def localized_translation(dua_id, english_fallback):
    parts = TRANSLATIONS.get(dua_id)
    if not parts:
        return _pack((english_fallback, "", "", "", ""), english_fallback)
    return _pack((parts[0] or english_fallback, parts[1], parts[2], parts[3], parts[4]), english_fallback)
